```type Foo = {
  foo?: {
    bar?: {
      baz: number;
    };
  };
  x: {
    y: {
      a: number,
      b: number
    }
  },
};

type ValueOf&lt;T&gt; = T[keyof T]
type SubPath&lt;T&gt; = {
  [P in keyof T]-?: [P] | [P, ...Path&lt;NonNullable&lt;T[P]&gt;&gt;]
}
type Path&lt;T&gt; = T extends number | string | null ? [] : ValueOf&lt;SubPath&lt;T&gt;&gt;

type Head&lt;I extends unknown[]&gt; = I extends [infer K, ...unknown[]] ? K : never
type Tail&lt;I extends unknown[]&gt; = I extends [unknown, ...infer R] ? R : never

type PrismLike&lt;T, I extends Path&lt;T&gt;&gt; =
  Head&lt;I&gt; extends keyof T
  ? Tail&lt;I&gt; extends []
    ? T[Head&lt;I&gt;]
    : Tail&lt;I&gt; extends Path&lt;NonNullable&lt;T[Head&lt;I&gt;]&gt;&gt;
      ? PrismLike&lt;NonNullable&lt;T[Head&lt;I&gt;]&gt;, Tail&lt;I&gt;&gt; : never
  : never

type Z = PrismLike&lt;Foo, ['foo', 'bar', 'baz']&gt;
type G = PrismLike&lt;Foo, ['x', 'z']&gt;```
なんとなく `G` の方はエラーになることは出来ますがエラーメッセージはいまいちですね。

