type PrismLike&lt;T, I extends unknown[]&gt; =
  Head&lt;I&gt; extends keyof T
  ? Tail&lt;I&gt; extends []
    ? T[Head&lt;I&gt;]
    : PrismLike&lt;NonNullable&lt;T[Head&lt;I&gt;]&gt;, Tail&lt;I&gt;&gt;
