```type Head&lt;T&gt; = T extends [any, ...any[]]
  ? ((...args: T) =&gt; any) extends (head: infer U, ...args: any[]) =&gt; any
    ? U
    : never
  : never;

type Tail&lt;T&gt; = T extends [any, any, ...any[]]
  ? ((...args: T) =&gt; any) extends (head: any, ...args: infer U) =&gt; any
    ? U
    : never
  : never;

type DeepNonNullable&lt;T, U extends readonly any[]&gt; = Head&lt;U&gt; extends keyof T
  ? Tail&lt;U&gt; extends never
    ? NonNullable&lt;T[Head&lt;U&gt;]&gt;
    : DeepNonNullable&lt;NonNullable&lt;T[Head&lt;U&gt;]&gt;, Tail&lt;U&gt;&gt;
  : never;

type Hoge = DeepNonNullable&lt;{
  bar?: {
    baz?: number;
  }
}, ["bar", "baz"]&gt;;```

